create table if not exists admins (id bigserial primary key,email text not null unique,password_hash text not null,role text not null default 'owner' check(role in ('owner','editor')),created_at timestamptz not null default now());
create table if not exists sessions (token_hash text primary key,admin_id bigint not null references admins(id) on delete cascade,expires_at timestamptz not null,created_at timestamptz not null default now());
create table if not exists login_attempts (email text primary key,failures integer not null default 0,locked_until timestamptz);
create table if not exists settings (key text primary key,value text not null default '');
create table if not exists services (slug text primary key,title text not null,summary text not null default '',body text not null default '',price text not null default 'Contact for pricing',active boolean not null default true,sort_order integer not null default 0);
create table if not exists posts (id bigserial primary key,slug text not null unique,title text not null,excerpt text not null default '',body text not null,category text not null default 'Pet care',published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists enquiries (id bigserial primary key,kind text not null check(kind in ('appointment','contact')),full_name text not null,email text not null,phone text not null,pet_name text,service text,message text not null default '',preferred_date date,preferred_time text,status text not null default 'new' check(status in ('new','contacted','confirmed','completed','cancelled')),created_at timestamptz not null default now());
create table if not exists products (id bigserial primary key,name text not null,description text not null default '',price text not null default 'Ask for price',category text not null default 'Pet essentials',available boolean not null default true,created_at timestamptz not null default now());
create table if not exists audit_logs (id bigserial primary key,admin_id bigint references admins(id) on delete set null,action text not null,entity text not null,entity_id text,created_at timestamptz not null default now());
create table if not exists request_limits (key text primary key,count integer not null default 0,window_start timestamptz not null default now());
create table if not exists media (id bigserial primary key,url text not null unique,pathname text not null,alt text not null,width integer not null,height integer not null,bytes integer not null,admin_id bigint references admins(id) on delete set null,created_at timestamptz not null default now());
